@Component("reservation-handler")
@ProcessingGroup("reservation-processing-group")
public class ReservationEventHandler {
	
	// core constructor
	ReservationEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateReservationEvent
     */
    @EventHandler
    public void handle( CreateReservationEvent event) {
        entityManager.persist(new Reservation(event.getReservationId(), event.getReferenceNumber(), event.getReservedQuantity(), event.getPromisedDate(), event.getSku(), event.getWarehouse(), event.getLocation(), event.getInventoryItem(), event.getLot(), event.getSerialNumbers(), event.getDemandSignal(), event.getReservationStatus(), event.getReservationType()));
    }

    /*
     * @param	event UpdateReservationEvent
     */
    @EventHandler
    public Reservation handle( UpdateReservationEvent event) {
    	entityManager.merge(new Reservation(event.getReservationId(), event.getReferenceNumber(), event.getReservedQuantity(), event.getPromisedDate(), event.getSku(), event.getWarehouse(), event.getLocation(), event.getInventoryItem(), event.getLot(), event.getSerialNumbers(), event.getDemandSignal(), event.getReservationStatus(), event.getReservationType()));
    }
    
    /*
     * @param	event DeleteReservationEvent
     */
    @EventHandler
    public void on( DeleteReservationEvent event) {
    	Reservation entity = new Reservation();
   
    	// ------------------------------------------
    	// apply the ReservationId
    	// ------------------------------------------
    	entity.setReservationId( event.getReservationId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ReservationRepository reservationEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ReservationEventHandler.class.getName());

}
